<script setup lang="ts">import { Head,Link,useForm } from '@inertiajs/vue3';import { Button } from '@/components/ui/button';import { Input } from '@/components/ui/input';const props=defineProps<{order:any;accounts:any[];authorizations:any[];canManage:boolean;canRequestAuthorization:boolean;now:string}>();const advance=useForm({amount:0,financial_account_id:props.accounts[0]?.id??'',paid_at:props.now,reference:''});const cancel=useForm({reason:''});const auth=useForm({reason:''});const confirm=useForm({});const money=(v:number)=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v||0);</script><template><Head :title="order.document_number"/><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex justify-between gap-3"><div><p class="text-sm text-muted-foreground">{{order.customer}} · {{order.price_list}}</p><h1 class="text-2xl font-semibold">{{order.document_number}}</h1><p class="text-sm text-muted-foreground">{{order.status_label}} · entrega {{order.due_at}}</p></div><div class="flex gap-2"><Button variant="outline" as-child><Link href="/orders">Volver</Link></Button><Button v-if="order.status==='draft'&&canManage" variant="outline" as-child><Link :href="`/orders/${order.id}/edit`">Editar</Link></Button><Button v-if="order.status==='draft'&&canManage" @click="confirm.post(`/orders/${order.id}/confirm`)">Confirmar</Button></div></header><section class="grid gap-3 sm:grid-cols-3"><div class="rounded-xl border bg-card p-4"><p class="text-xs text-muted-foreground">Total</p><strong class="text-xl">{{money(order.total)}}</strong></div><div class="rounded-xl border bg-card p-4"><p class="text-xs text-muted-foreground">Anticipos</p><strong class="text-xl">{{money(order.advance_amount)}}</strong></div><div class="rounded-xl border bg-card p-4"><p class="text-xs text-muted-foreground">Saldo</p><strong class="text-xl">{{money(order.balance_amount)}}</strong></div></section><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Producto</th><th class="px-4 py-3">Pedido</th><th class="px-4 py-3">Reservado</th><th class="px-4 py-3">Producido</th><th class="px-4 py-3">Precio</th><th class="px-4 py-3">Total</th></tr></thead><tbody class="divide-y"><tr v-for="line in order.lines" :key="line.id"><td class="px-4 py-3">{{line.product}}<p v-if="line.price_reason" class="text-xs text-muted-foreground">{{line.price_reason}}</p></td><td class="px-4 py-3">{{line.ordered_quantity}}</td><td class="px-4 py-3">{{line.reserved_quantity}}</td><td class="px-4 py-3">{{line.produced_quantity}}</td><td class="px-4 py-3">{{money(line.unit_price)}}<small v-if="line.unit_price!==line.list_unit_price" class="block text-muted-foreground">Lista {{money(line.list_unit_price)}}</small></td><td class="px-4 py-3">{{money(line.line_total)}}</td></tr></tbody></table></section><div class="grid gap-5 lg:grid-cols-2"><section v-if="canManage&&order.status!=='cancelled'&&order.status!=='delivered'" class="rounded-xl border bg-card p-4"><h2 class="font-semibold">Registrar anticipo</h2><form class="mt-3 grid gap-3" @submit.prevent="advance.post(`/orders/${order.id}/advances`,{onSuccess:()=>advance.reset('amount','reference')})"><Input v-model.number="advance.amount" type="number" min="1" :max="order.balance_amount" placeholder="Valor en COP"/><select v-model="advance.financial_account_id" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option v-for="account in accounts" :key="account.id" :value="account.id">{{account.name}}</option></select><Input v-model="advance.paid_at" type="datetime-local"/><Input v-model="advance.reference" placeholder="Referencia opcional"/><Button type="submit">Registrar anticipo</Button></form><div v-if="order.advances.length" class="mt-3 divide-y"><p v-for="item in order.advances" :key="item.id" class="py-2 text-sm">{{money(item.amount)}} · {{item.paid_at}} · {{item.reference||'Sin referencia'}}</p></div></section><section class="rounded-xl border bg-card p-4"><h2 class="font-semibold">Historial</h2><div class="mt-3 divide-y"><div v-for="item in order.histories" :key="item.id" class="py-2 text-sm"><p>{{item.from||'Inicio'}} → {{item.to}}</p><small class="text-muted-foreground">{{item.at}} · {{item.by}} · {{item.notes}}</small></div></div></section></div><section v-if="order.status==='draft'&&canRequestAuthorization" class="rounded-xl border border-amber-300 p-4"><h2 class="font-semibold">Precio inferior al mínimo</h2><form class="mt-3 flex gap-2" @submit.prevent="auth.post(`/orders/${order.id}/price-authorization`)"><Input v-model="auth.reason" required placeholder="Motivo de la excepción"/><Button type="submit" variant="outline">Solicitar autorización</Button></form></section><section v-if="canManage&&order.status!=='cancelled'&&order.status!=='delivered'" class="rounded-xl border border-destructive/30 p-4"><h2 class="font-semibold">Cancelar pedido</h2><form class="mt-3 flex gap-2" @submit.prevent="cancel.post(`/orders/${order.id}/cancel`)"><Input v-model="cancel.reason" required placeholder="Motivo"/><Button type="submit" variant="destructive">Cancelar</Button></form></section></main></template>
